<?php

declare(strict_types=1);

namespace Nesto\Tests\Orm\Fixtures\Columns;

use Nesto\Orm\Attributes\Column;
use Nesto\Orm\Attributes\Entity;
use Nesto\Orm\Attributes\ManyToOne;
use Nesto\Orm\Attributes\PrimaryGeneratedColumn;

/** uuid primary key (PostgreSQL: gen_random_uuid() default, elsewhere generated by the ORM). */
#[Entity(name: 'col_vouchers')]
final class Voucher
{
    #[PrimaryGeneratedColumn('uuid')]
    public string $id;

    #[Column(length: 20)]
    public string $code;

    #[ManyToOne(Customer::class, nullable: true)]
    public ?Customer $customer = null;
}
